arguments.command:
curl -s -X POST https://slack.com/api/conversations.list -d "token=<TOKEN>&types=public_channel&limit=1000" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERROR:', d.get('error'), d.get('error_summary')); sys.exit(1)
for c in d['channels']:
    if 'launch' in c['name']:
        print(c['id'], c['name'])
"

